<script setup lang="ts">
import AppSelect from '../common/AppSelect.vue'
import { onMounted,reactive,ref } from 'vue'
import { documentsApi,type PolicyMetadata } from '../../api/documents'
const props=defineProps<{documentId:string}>()
const form=reactive<PolicyMetadata>({issuer:'',document_number:'',regions:[],category:'',audience:'',published_on:null,effective_on:null,expires_on:null,validity:'unknown',verification_source:'',verified_on:null,amends:[],replaces:[],notes:''})
const regions=ref(''),amends=ref(''),replaces=ref(''),busy=ref(true),loaded=ref(false),error=ref(''),saved=ref('')
const dates=[['published_on','发布日期'],['effective_on','施行日期'],['expires_on','失效日期'],['verified_on','核验日期']] as const
onMounted(async()=>{try{const doc=await documentsApi.detail(props.documentId);if(doc.policy_metadata){Object.assign(form,doc.policy_metadata);regions.value=form.regions.join('\n');amends.value=form.amends.join('\n');replaces.value=form.replaces.join('\n')}loaded.value=true}catch(e){error.value=e instanceof Error?e.message:'政策信息加载失败'}finally{busy.value=false}})
const lines=(value:string)=>value.split(/[\n,，]/).map(s=>s.trim()).filter(Boolean)
async function save(){if(!loaded.value)return;busy.value=true;error.value='';saved.value='';try{await documentsApi.savePolicy(props.documentId,{...form,regions:lines(regions.value),amends:lines(amends.value),replaces:lines(replaces.value)});saved.value='政策信息已保存，后续检索会携带这些标签。'}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
</script>
<template><details class="policy-editor"><summary>政策结构化信息（人工维护）</summary><p class="muted">按原文填写；未知项可留空。效力标签需要核验来源与日期，历史核验不代表今日仍有效。</p><form @submit.prevent="save"><fieldset :disabled="busy||!loaded" class="policy-fields"><label>发布机关<input v-model="form.issuer" class="input" maxlength="200"></label><label>文件文号<input v-model="form.document_number" class="input" maxlength="100"></label><label>政策类别<input v-model="form.category" class="input" maxlength="100"></label><label>适用地区（每行一项）<textarea v-model="regions" class="input" rows="2"></textarea></label><label>适用对象<textarea v-model="form.audience" class="input" rows="2" maxlength="1000"></textarea></label><label v-for="[key,label] in dates" :key="key">{{label}}<input class="input" type="date" :value="form[key]||''" @input="form[key]=($event.target as HTMLInputElement).value||null"></label><label>核验时的效力状态<AppSelect v-model="form.validity" class="select" :disabled="busy||!loaded"><option value="unknown">待核实</option><option value="effective">核验时有效</option><option value="repealed">已废止</option><option value="expired">已到期</option></AppSelect></label><label>核验来源<input v-model="form.verification_source" class="input" maxlength="1000"></label><label>修改的文件文号（每行一项）<textarea v-model="amends" class="input" rows="2"></textarea></label><label>替代的文件文号（每行一项）<textarea v-model="replaces" class="input" rows="2"></textarea></label><label>备注<textarea v-model="form.notes" class="input" rows="2" maxlength="2000"></textarea></label><button class="btn primary" type="submit">{{busy?'处理中…':'保存政策信息'}}</button></fieldset></form><p v-if="error" role="alert" class="document-error">{{error}}</p><p v-if="saved" role="status">{{saved}}</p></details></template>
<style scoped>
.policy-editor{margin:16px 0;padding:12px;border:1px solid var(--line);border-radius:8px}.policy-editor summary{cursor:pointer}.policy-fields{border:0;padding:12px 0;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:12px}.policy-fields label{display:flex;flex-direction:column;gap:6px;min-width:0}.policy-fields input,.policy-fields textarea,.policy-fields .select{width:100%;box-sizing:border-box}.policy-fields button{align-self:end;min-height:44px}
</style>
